using Godot;
using Godot.Collections;
using GArray = Godot.Collections.Array;
using StringConfigDictionary = System.Collections.Generic.Dictionary<string, CharacterGenerator.Config>;

/// <summary>按境界分布创建 HumanData，并提供灵根、性格及外观辅助逻辑。</summary>
public partial class CharacterGenerator : RefCounted
{
    internal sealed record Config(float StatMean, float StatStd, float StatMin, float StatMax, float SpiritMean, float SpiritStd, float SpiritMin, float SpiritMax, int CoreMin, int CoreMax, int AgeMin, int AgeMax, int AgeBonus, float MaleRatio);
    private static readonly StringConfigDictionary Configs = new()
    {
        ["凡人"] = new(5.5f,1.5f,2,10,0,0,0,0,0,0,16,60,30,.5f), ["云息"] = new(8,2,3,14,25,10,10,60,0,0,18,80,50,.55f),
        ["玄基"] = new(12,3,5,22,65,20,30,140,1,1,25,150,100,.55f), ["金丹"] = new(18,4,8,35,200,60,80,420,1,3,35,300,250,.5f),
        ["神胎"] = new(30,8,15,60,500,150,200,1100,3,5,60,500,500,.5f), ["天人"] = new(55,15,30,120,1500,450,600,3200,5,9,100,1000,1000,.5f)
    };
    private static readonly string[] Elements = ["METAL", "WOOD", "WATER", "FIRE", "EARTH"], ElementNames = ["金", "木", "水", "火", "土"];
    private static readonly (string Name, string Summary, float Social, float Management, float Charisma)[] Personalities = [("温厚","善于安抚人心，带着自己人出面时更容易让场面和缓。",7,4,4),("圆融","擅长周旋应对，多方往来时尤其容易把局面盘活。",10,5,7),("机敏","反应快，眼光活，最适合试探口风与摸消息。",6,3,2),("沉稳","气定神闲，重在压得住场，也耐得住长期经营。",2,9,3),("细谨","条理分明，最擅长盯流程、管账目和稳妥周转。",3,11,0),("果决","出手利落，适合当机立断地推动事情落地。",4,8,3),("刚直","不喜虚与委蛇，但真诚直接，容易建立信服感。",5,6,1),("清峻","寡言自持，不喜喧闹，独自行事时往往更见锋芒。",2,7,2)];

    public HumanData generate(string realm, int faction = 0, HumanData? template = null)
    {
        if (!Configs.TryGetValue(realm, out var cfg)) cfg = Configs["凡人"];
        var data = new HumanData { cultivation_realm = realm, faction = faction };
        data.base_physique = normal(cfg.StatMean,cfg.StatStd,cfg.StatMin,cfg.StatMax); data.base_intelligence = normal(cfg.StatMean,cfg.StatStd,cfg.StatMin,cfg.StatMax); data.base_agility = normal(cfg.StatMean,cfg.StatStd,cfg.StatMin,cfg.StatMax); data.base_soul = normal(cfg.StatMean,cfg.StatStd,cfg.StatMin,cfg.StatMax);
        data.base_fortune = normal(Mathf.Min(75, cfg.StatMean + 44.5f),15,20,100); data.base_comprehension = normal(Mathf.Min(75,cfg.StatMean+44.5f),15,20,100); data.base_charisma = normal(Mathf.Min(75,cfg.StatMean+44.5f),15,20,100); data.base_social = data.base_charisma; data.base_management = data.base_charisma;
        data.base_sword_proficiency=proficiency(cfg); data.base_blade_proficiency=proficiency(cfg); data.base_spear_proficiency=proficiency(cfg); data.base_body_proficiency=proficiency(cfg); data.base_magic_proficiency=proficiency(cfg); data.base_forging_proficiency=proficiency(cfg); data.base_talisman_proficiency=proficiency(cfg); data.base_formation_proficiency=proficiency(cfg); data.base_alchemy_proficiency=proficiency(cfg);
        data.spirit_strands = Mathf.RoundToInt(normal(cfg.SpiritMean,cfg.SpiritStd,cfg.SpiritMin,cfg.SpiritMax)); data.core_count = GD.RandRange(cfg.CoreMin,cfg.CoreMax); data.current_age = GD.RandRange(cfg.AgeMin,cfg.AgeMax); data.max_age = data.current_age + GD.RandRange(10,cfg.AgeBonus); data.gender = GD.Randf() < cfg.MaleRatio ? 0 : 1; data.entity_name = new NameGenerator().generate_full(data.gender);
        assign_random_appearance(data); assign_random_personality(data); generate_spirit_root(data); if (template is not null) apply_template(data,template); sync_derived(data); return data;
    }
    public Array<HumanData> generate_world_npcs(Dictionary distribution, int faction = 0) { var result = new Array<HumanData>(); foreach (var pair in distribution) for (var i=0;i<pair.Value.AsInt32();i++) result.Add(generate(pair.Key.AsString(),faction)); return result; }
    public HumanData? generate_from_template(string template_path) { var template = ResourceLoader.Load<HumanData>(template_path); return template is null ? null : generate(string.IsNullOrEmpty(template.cultivation_realm) ? "凡人" : template.cultivation_realm, template.faction, template); }
    public static void assign_random_appearance(HumanData data) { data.appearance_seed=(int)GD.Randi(); data.appearance_face_style=GD.RandRange(0,4); data.appearance_eyebrow_style=GD.RandRange(0,4); data.appearance_eye_style=GD.RandRange(0,4); data.appearance_nose_style=GD.RandRange(0,4); data.appearance_mouth_style=GD.RandRange(0,4); data.appearance_skin_tone=GD.RandRange(0,4); data.appearance_hair_color=GD.RandRange(0,3); data.appearance_hair_style=GD.RandRange(0,4); data.appearance_beard_style=-1; data.appearance_face_width=Mathf.Lerp(.96f,1.04f,GD.Randf()); data.appearance_face_height=Mathf.Lerp(.97f,1.03f,GD.Randf()); data.appearance_eye_scale=Mathf.Lerp(.96f,1.06f,GD.Randf()); data.appearance_eye_offset_y=GD.RandRange(-3,3); data.appearance_clothes_style=0; data.appearance_accessory_style=-1; }
    public static void inherit_appearance(HumanData child, HumanData? parent_a, HumanData? parent_b, float mutation_chance = .08f) { if (child is null) return; child.appearance_seed=(int)GD.Randi(); foreach(var field in new[]{"appearance_face_style","appearance_eyebrow_style","appearance_eye_style","appearance_nose_style","appearance_mouth_style","appearance_skin_tone","appearance_hair_color","appearance_hair_style"}) { var source = GD.Randf()<.5f ? parent_a : parent_b; child.Set(field,source is null || GD.Randf()<mutation_chance ? GD.RandRange(0,4) : source.Get(field)); } child.appearance_clothes_style=0; child.appearance_accessory_style=-1; child.appearance_beard_style=-1; child.appearance_face_width=parent_a is null||parent_b is null?1:Mathf.Clamp((parent_a.appearance_face_width+parent_b.appearance_face_width)*.5f,.9f,1.1f); child.appearance_face_height=parent_a is null||parent_b is null?1:Mathf.Clamp((parent_a.appearance_face_height+parent_b.appearance_face_height)*.5f,.9f,1.1f); child.appearance_eye_scale=parent_a is null||parent_b is null?1:Mathf.Clamp((parent_a.appearance_eye_scale+parent_b.appearance_eye_scale)*.5f,.9f,1.15f); child.appearance_eye_offset_y=0; }
    public static void assign_random_personality(HumanData data) { if (data is null || !string.IsNullOrWhiteSpace(data.personality)) return; var p=Personalities[GD.RandRange(0,Personalities.Length-1)]; data.personality=p.Name; data.base_social=Mathf.Clamp(data.base_social+p.Social,20,100); data.base_management=Mathf.Clamp(data.base_management+p.Management,20,100); data.base_charisma=Mathf.Clamp(data.base_charisma+p.Charisma,20,100); }
    public static Dictionary get_personality_profile(string name) { foreach(var p in Personalities) if(p.Name==name) return new Dictionary{{"name",p.Name},{"summary",p.Summary},{"social_bias",p.Social},{"management_bias",p.Management},{"charisma_bias",p.Charisma}}; return []; }
    public static Dictionary get_personality_notes(string name) { var p=get_personality_profile(name); return new Dictionary{{"summary",p.TryGetValue("summary",out var summary)?summary:"尚无明确倾向。"},{"strengths",new Array<string>()},{"weaknesses",new Array<string>()}}; }
    public static string format_personality_tooltip(string name) => "性格：" + name + "\n" + get_personality_notes(name)["summary"].AsString();
    public static string format_weight_summary(GArray weights) { var parts=new List<string>(); for(var i=0;i<Math.Min(5,weights.Count);i++) if(weights[i].AsInt32()>0) parts.Add($"{ElementNames[i]}:{weights[i].AsInt32()}"); return parts.Count==0?"无灵根":string.Join("   ",parts); }
    private static float proficiency(Config cfg) => normal(cfg.StatMean * .82f + .5f, cfg.StatStd, cfg.StatMin, cfg.StatMax);
    private static float normal(float mean,float std,float min,float max) { if(std==0) return mean; var u=Mathf.Max(GD.Randf(),.000001f); var z=Mathf.Sqrt(-2*Mathf.Log(u))*Mathf.Cos(Mathf.Tau*GD.Randf()); return Mathf.Snapped(Mathf.Clamp(mean+z*std,min,max),.1f); }
    private static void generate_spirit_root(HumanData data) { var roll=GD.RandRange(1,100); var count=roll<=5?0:roll<=45?1:roll<=70?2:roll<=85?3:roll<=95?4:5; var weights=new GArray{0,0,0,0,0}; if(count==0){data.spirit_root_type=0;data.spirit_root_name="无灵根";data.spirit_element=0;data.root_weights=weights;return;} var selected=Elements.OrderBy(_=>GD.Randi()).Take(count).OrderBy(e=>System.Array.IndexOf(Elements,e)).ToArray(); var baseWeight=count switch{1=>80,2=>45,3=>30,4=>25,_=>20}; foreach(var element in selected) weights[System.Array.IndexOf(Elements,element)]=baseWeight; var remaining=count switch{1=>20,2=>10,3=>10,_=>0}; while(remaining-->0) { var index=GD.RandRange(0,4); weights[index]=weights[index].AsInt32()+1; } data.root_weights=weights; data.spirit_root_type=spirit_root_type(selected); data.spirit_root_name=string.Concat(selected.Select(e=>ElementNames[System.Array.IndexOf(Elements,e)]))+(count==1?"灵根（天灵根）":"灵根"); data.spirit_element=System.Array.IndexOf(Elements,selected[0])+1; }
    private static int spirit_root_type(string[] selected) { var combinations=new[]{"METAL","WOOD","WATER","FIRE","EARTH","METAL_WOOD","METAL_WATER","METAL_FIRE","METAL_EARTH","WOOD_WATER","WOOD_FIRE","WOOD_EARTH","WATER_FIRE","WATER_EARTH","FIRE_EARTH","METAL_WOOD_WATER","METAL_WOOD_FIRE","METAL_WOOD_EARTH","METAL_WATER_FIRE","METAL_WATER_EARTH","METAL_FIRE_EARTH","WOOD_WATER_FIRE","WOOD_WATER_EARTH","WOOD_FIRE_EARTH","WATER_FIRE_EARTH","METAL_WOOD_WATER_FIRE","METAL_WOOD_WATER_EARTH","METAL_WOOD_FIRE_EARTH","METAL_WATER_FIRE_EARTH","WOOD_WATER_FIRE_EARTH","METAL_WOOD_WATER_FIRE_EARTH"}; return System.Array.IndexOf(combinations,string.Join('_',selected))+1; }
    private static void sync_derived(HumanData d) { d.physique=d.base_physique;d.intelligence=d.base_intelligence;d.agility=d.base_agility;d.soul=d.base_soul;d.fortune=d.base_fortune;d.comprehension=d.base_comprehension;d.charisma=d.base_charisma;d.social=d.base_social;d.management=d.base_management;d.sword_proficiency=d.base_sword_proficiency;d.blade_proficiency=d.base_blade_proficiency;d.spear_proficiency=d.base_spear_proficiency;d.body_proficiency=d.base_body_proficiency;d.magic_proficiency=d.base_magic_proficiency;d.forging_proficiency=d.base_forging_proficiency;d.talisman_proficiency=d.base_talisman_proficiency;d.formation_proficiency=d.base_formation_proficiency;d.alchemy_proficiency=d.base_alchemy_proficiency;d.max_health=Mathf.RoundToInt(60+d.physique*8+d.agility*3+d.soul*3+d.intelligence*1.5f);d.current_health=d.max_health;d.max_mind=Mathf.RoundToInt(30+d.soul*4+d.intelligence*1.5f+d.physique*.5f);d.current_mind=d.max_mind;d.precision=Mathf.RoundToInt(d.intelligence*4+d.agility*3+d.soul+d.physique*.5f);d.dodge=Mathf.RoundToInt(d.agility*4+d.soul*2+d.intelligence+d.physique*.5f);d.critical=Mathf.RoundToInt(d.physique*.5f+d.agility*.8f+d.soul*1.2f+d.intelligence*.3f);d.crit_resist=Mathf.RoundToInt(d.physique*3+d.intelligence*2+d.agility*2+d.soul*1.5f);d.initiative_speed=Creature.calculate_base_initiative_speed(d.physique,d.intelligence,d.agility,d.soul); }
    private static void apply_template(HumanData d,HumanData t) { foreach(var field in new[]{"entity_name","cultivation_realm","personality","destiny_title","basic_deck_path","main_gongfa_path","weapon_path","clothes_path","ornament_1_path","ornament_2_path","vehicle_path"}) if(!string.IsNullOrEmpty(t.Get(field).AsString())) d.Set(field,t.Get(field).AsString()); foreach(var field in new[]{"base_physique","base_intelligence","base_agility","base_soul","base_fortune","base_comprehension","base_charisma","base_social","base_management","base_sword_proficiency","base_blade_proficiency","base_spear_proficiency","base_body_proficiency","base_magic_proficiency","base_forging_proficiency","base_talisman_proficiency","base_formation_proficiency","base_alchemy_proficiency","max_age","current_age","spirit_strands","core_count"}) if(t.Get(field).AsSingle()>0)d.Set(field,t.Get(field)); if(t.gender>=0)d.gender=t.gender; if(t.faction!=0)d.faction=t.faction; if(t.spirit_root_type>=0){d.spirit_root_type=t.spirit_root_type;d.spirit_root_name=t.spirit_root_name;d.spirit_element=t.spirit_element;d.root_weights=t.root_weights.Duplicate();} foreach(var path in t.sub_gongfa_paths)d.sub_gongfa_paths.Add(path); foreach(var path in t.learned_gongfa_paths)d.learned_gongfa_paths.Add(path); foreach(var path in t.loaded_skill_paths)d.loaded_skill_paths.Add(path); foreach(var path in t.inventory_item_paths)d.inventory_item_paths.Add(path); foreach(var count in t.inventory_item_counts)d.inventory_item_counts.Add(count); foreach(var artifact in t.artifact_inventory)if(artifact is not null)d.artifact_inventory.Add(artifact.Duplicate(true) as ArtifactInstanceData ?? artifact); foreach(var id in t.equipped_artifact_ids)d.equipped_artifact_ids.Add(id); }
}
